from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data["packages"]
    names = sorted(packages)
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    active_features = set(data.get("features", []))

    constraints = {
        name: [(bounds[0], bounds[1])]
        for name, bounds in data["roots"].items()
    }
    best_vector = None
    best_versions = None
    visited = set()

    def dependency_active(dep):
        feature = dep.get("feature")
        return not feature or feature in active_features

    def allowed(name, ranges):
        if name not in packages:
            return []
        forbidden = blocked.get(name, [])
        return [
            index
            for index, row in enumerate(packages[name])
            if row["version"] not in forbidden
            and (name not in pins or row["version"] == pins[name])
            and all(low <= row["version"] <= high for low, high in ranges)
        ]

    def is_acyclic(selected):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            row = packages[name][selected[name]]
            for dep in row["deps"]:
                if dependency_active(dep) and not visit(dep["name"]):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in selected)

    def search(current_constraints, selected):
        nonlocal best_vector, best_versions

        state = (
            tuple(sorted(selected.items())),
            tuple(
                (name, tuple(sorted(ranges)))
                for name, ranges in sorted(current_constraints.items())
            ),
        )
        if state in visited:
            return
        visited.add(state)

        for name, index in selected.items():
            version = packages[name][index]["version"]
            if name not in current_constraints or not all(
                low <= version <= high
                for low, high in current_constraints[name]
            ):
                return

        upper = []
        for name in names:
            if name in selected:
                upper.append(packages[name][selected[name]]["version"])
            else:
                ranges = current_constraints.get(name, [])
                candidates = allowed(name, ranges) if ranges else allowed(name, [])
                if name in current_constraints and not candidates:
                    return
                upper.append(
                    max((packages[name][i]["version"] for i in candidates), default=-1)
                )
        upper = tuple(upper)
        if best_vector is not None and upper <= best_vector:
            return

        unresolved = sorted(set(current_constraints) - set(selected))
        if not unresolved:
            if is_acyclic(selected):
                vector = tuple(
                    packages[name][selected[name]]["version"] if name in selected else -1
                    for name in names
                )
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_versions = {
                        name: packages[name][index]["version"]
                        for name, index in selected.items()
                    }
            return

        name = unresolved[0]
        for index in allowed(name, current_constraints[name]):
            next_selected = dict(selected)
            next_selected[name] = index
            next_constraints = {
                package: list(ranges)
                for package, ranges in current_constraints.items()
            }
            for dep in packages[name][index]["deps"]:
                if dependency_active(dep):
                    next_constraints.setdefault(dep["name"], []).append(
                        (dep["min"], dep["max"])
                    )
            search(next_constraints, next_selected)

    search(constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
